import test from 'node:test';import assert from 'node:assert/strict';
import {CHAPTER_01} from './chapter01-data.js';
import {createChapterProgress,advanceChapter,sceneReady,readChapterProgress,writeChapterProgress,chapterStorageKey} from './chapter01-engine.mjs';
const first=CHAPTER_01.scenes[0],second=CHAPTER_01.scenes[1];
function finishOpening(){let p=createChapterProgress();for(let i=0;i<first.dialogue.length;i++)p=advanceChapter(p,{type:'line',delta:1});p=advanceChapter(p,{type:'inspect',id:'inspect_city_panel'});return advanceChapter(p,{type:'choice',id:'help'});}
test('Scene 01 needs dialogue, one evidence and any opening choice; cannot jump scene',()=>{let p=createChapterProgress();assert.equal(advanceChapter(p,{type:'next'}).sceneIndex,0);assert.equal(advanceChapter(p,{type:'choice',id:'help'}).scenes[first.id].choice,null);p=finishOpening();for(const c of first.choices){const a=advanceChapter(p,{type:'choice',id:c.id});assert.ok(sceneReady(first,a));assert.equal(advanceChapter(a,{type:'next'}).sceneIndex,1);}});
test('Scene 02 requires two distinct evidence; wrong answers retry; ending must be read',()=>{let p=advanceChapter(finishOpening(),{type:'next'});for(let i=0;i<8;i++)p=advanceChapter(p,{type:'line',delta:1});p=advanceChapter(p,{type:'inspect',id:'inspect_registration'});p=advanceChapter(p,{type:'inspect',id:'inspect_registration'});assert.equal(p.scenes[second.id].seen.length,1);assert.equal(advanceChapter(p,{type:'choice',id:'review'}).scenes[second.id].choice,null);p=advanceChapter(p,{type:'inspect',id:'inspect_bias_log'});for(const id of ['accept','delete']){p=advanceChapter(p,{type:'choice',id});assert.equal(sceneReady(second,p),false);}p=advanceChapter(p,{type:'choice',id:'review'});assert.equal(sceneReady(second,p),false);p=advanceChapter(p,{type:'ending'});assert.ok(sceneReady(second,p));assert.equal(advanceChapter(p,{type:'next'}).sceneIndex,1);});
test('Back and reload preserve inspected evidence and dialogue; isolate accounts',()=>{const map=new Map(),storage={getItem:k=>map.get(k)||null,setItem:(k,v)=>map.set(k,v)};const p=advanceChapter(finishOpening(),{type:'next'});writeChapterProgress(storage,'one',p);assert.deepEqual(readChapterProgress(storage,'one'),p);assert.equal(readChapterProgress(storage,'two').sceneIndex,0);assert.equal(advanceChapter(p,{type:'back'}).scenes[first.id].choice,'help');assert.notEqual(chapterStorageKey('one'),chapterStorageKey('two'));});
test('Malformed saved IDs are ignored and cannot skip unfinished opening',()=>{const p=createChapterProgress({chapterId:CHAPTER_01.chapterId,sceneIndex:1,scenes:{[first.id]:{seen:['fake','inspect_city_panel','inspect_city_panel'],line:-9,choice:'fake'}}});assert.equal(p.sceneIndex,0);assert.deepEqual(p.scenes[first.id].seen,['inspect_city_panel']);assert.equal(p.scenes[first.id].line,0);assert.equal(p.scenes[first.id].choice,null);});
test('Storage failures surface; no pretend successful save or destructive corrupt-data recovery',()=>{assert.throws(()=>writeChapterProgress({setItem(){throw Error('quota')}},'one',finishOpening()),/quota/);assert.throws(()=>readChapterProgress({getItem:()=>'{bad'},'one'));assert.throws(()=>chapterStorageKey(''),/AUTH_REQUIRED/);});
test('Round 1 is two scenes only and does not include quiz keys or inventory trial/reward grants',()=>{assert.equal(CHAPTER_01.scenes.length,2);assert.doesNotMatch(JSON.stringify(CHAPTER_01),/rewardCardId|quizAnswer|trialCardId/);});
